package com.mamtrex.hospital.bed;
import com.mamtrex.hospital.audit.AuditService; import com.mamtrex.hospital.shared.NotFoundException; import jakarta.validation.Valid; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/beds") public class BedController { private final BedRepository repo; private final AuditService audit; public BedController(BedRepository r,AuditService a){repo=r;audit=a;} public record Request(@jakarta.validation.constraints.NotBlank String ward, @jakarta.validation.constraints.NotBlank String room, @jakarta.validation.constraints.NotBlank String bedNumber, @jakarta.validation.constraints.NotBlank String occupancyStatus, @jakarta.validation.constraints.NotBlank String patientId){} @PostMapping public Bed create(@Valid @RequestBody Request r){var e=repo.save(new Bed(r.ward(), r.room(), r.bedNumber(), r.occupancyStatus(), r.patientId()));audit.record("CREATE","Bed",e.getId().toString(),"created");return e;} @GetMapping public List<Bed> list(){return repo.findAll();} @GetMapping("/{id}") public Bed get(@PathVariable UUID id){return repo.findById(id).orElseThrow(()->new NotFoundException("Bed not found: "+id));} @DeleteMapping("/{id}") public void delete(@PathVariable UUID id){if(!repo.existsById(id))throw new NotFoundException("Bed not found: "+id);repo.deleteById(id);audit.record("DELETE","Bed",id.toString(),"deleted");} }
